module fsm (
  input clk,
  input reset,
  input f,
  output reg n);parameter S0=0, S1=1, S2=2, S3=3;
	reg [1:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= S2;
		else state <= next;
	end

	always_comb begin
		case (state)
			S0: next = f ? S2 : S1;
			S1: next = f ? S0 : S3;
			S2: next = f ? S3 : S0;
			S3: next = f ? S1 : S2;
			default: next = 'x;
		endcase
	end

	assign n = (state == S0) || (state == S2);

endmodule

