module reg_file(
  input clk,
  input rst,
  input we1,
  input we2,
  input [4:0] waddr1,
  input [4:0] waddr2,
  input [31:0] wdata1,
  input [31:0] wdata2,
  input [4:0] raddr1,
  input [4:0] raddr2,
  input [4:0] raddr3,
  input [4:0] raddr4,
  output reg [31:0] rdata1,
  output reg [31:0] rdata2,
  output reg [31:0] rdata3,
  output reg [31:0] rdata4
);

  reg [31:0] regfile [31:0];

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      integer i;
      for (i = 0; i < 32; i = i + 1)
        regfile[i] <= 32'd0;
    end else begin
      if (we1)
        regfile[waddr1] <= wdata1;
      if (we2)
        regfile[waddr2] <= wdata2;
    end
  end

  always @(*) begin
    rdata1 = regfile[raddr1];
    rdata2 = regfile[raddr2];
    rdata3 = regfile[raddr3];
    rdata4 = regfile[raddr4];
  end

endmodule

