module top_module (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter G=0, H=1, I=2;

    always_comb begin
		case (state)
			G: next_state = in ? I : H;
			H: next_state = in ? G : I;
			I: next_state = in ? H : G;
		endcase
    end

    always_comb begin
		case (state)
			G: out = in ? 1 : 0;
			H: out = in ? 0 : 1;
			I: out = in ? 1 : 0;
		endcase
    end

endmodule

