        case (funct)
            (6'b100000): ALUctl = 4'b0010;  
            (6'b100010): ALUctl = 4'b0110;  
            (6'b100100): ALUctl = 4'b0000;  
            (6'b100101): ALUctl = 4'b0001;  
            (6'b101010): ALUctl = 4'b0111;  
        endcase
    end
endcase
end
endmodule

