	input wire io_out_rdy,
	output reg io_out_vld,

	input wire [4:0] io_err);(* mark_debug = "true" *) reg [2:0] loop_state;

	always @(posedge clk) begin
		if (~rstn) begin
			io_in_rdy <= 0;
			io_out_vld <= 0;
			loop_state <= 0;
