			io_in_rdy <= 0;
			io_out_data <= io_in_data;
			io_out_vld <= 1;
			loop_state <= 2;
		end else if (loop_state == 2 && io_out_rdy && io_out_vld) begin
			io_out_vld <= 0;
			loop_state <= 0;
		end
	end
endmodule

