module mux_16to1(
    input wire a,
    input wire b,
    input wire c,
    input wire d,
    input wire e,
    input wire f,
    input wire g,
    input wire h,
    input wire i,
    input wire j,
    input wire k,
    input wire l,
    input wire m,
    input wire n,
    input wire o,
    input wire p,
    input wire [3:0] sel,
    output reg y
);

