            4'b1000: y = i;
            4'b1001: y = j;
            4'b1010: y = k;
            4'b1011: y = l;
            4'b1100: y = m;
            4'b1101: y = n;
            4'b1110: y = o;
            4'b1111: y = p;
            default: y = 1'b0;
        endcase
    end
endmodule

