module top_module(
        input   wire [31:0]   op1,
        input   wire [5:0]    shamt,
        input   wire [1:0]    operation,
        output  wire [31:0]   res
    );reg [31:0] shift_res;

    assign res = shift_res;

    always @ *
    case (operation)
        2'b01: shift_res = (op1 <<  shamt); 
        2'b10: shift_res = (op1 >>  shamt); 
        2'b11: shift_res = (op1 >>> shamt); 
