  state <= 4'h0; 
  full <= 1; 
  end else begin 
  if (count == 0) begin 
  state <= state + 1; 
  shift[8:0] <= { serial_s, shift[8:1] }; 
  count <= 1302; 
  end else begin 
  count <= count - 1; 
  end 
  end 
  end 
  end 
